// ---------------- helpers ----------------
function randn(mean, std) {
    let u = 1 - Math.random();
    let v = 1 - Math.random();
    return Math.sqrt(-2.0 * Math.log(u)) * Math.cos(2.0 * Math.PI * v) * std + mean;
}
function smooth(prev, next, alpha) {
    return (prev === undefined) ? next : prev + alpha * (next - prev);
}
const α = 0.2;                          // 平滑系数，可调小一点更平滑
let last = context.get('last') || {};   // 取出上一次值

// --------------- raw simulation ---------------
let windSpeedRaw   = Math.max(0, randn(10, 3));
let rotorSpeedRaw  = (windSpeedRaw < 3 || windSpeedRaw > 25)
                   ? 0
                   : (windSpeedRaw <= 12
                      ? windSpeedRaw / 12 * 25
                      : 25) + randn(0, 1);
let temperatureRaw = Math.min(90, Math.max(30, randn(55, 8)));
let vibrationRaw   = Math.abs(randn(1.5, 1.0));
let powerRaw       = (windSpeedRaw < 3 || windSpeedRaw > 25)
                   ? 0
                   : (windSpeedRaw <= 12
                      ? Math.pow(windSpeedRaw / 12, 3) * 2300
                      : 2300);

// 故障注入保持原逻辑
if (Math.random() < 0.05 && windSpeedRaw >= 3 && windSpeedRaw <= 25) {
    temperatureRaw += 20 + Math.random() * 5;
    vibrationRaw   += 4  + Math.random() * 2;
}

// --------------- apply smoothing ---------------
let windSpeed   = smooth(last.windSpeed,   windSpeedRaw,   α);
let rotorSpeed  = smooth(last.rotorSpeed,  rotorSpeedRaw,  α);
let temperature = smooth(last.temperature, temperatureRaw, α);
let vibration   = smooth(last.vibration,   vibrationRaw,   α);
let power       = smooth(last.power,       powerRaw,       α);

// --------------- assemble object ---------------
let p = {
    turbineId:   "T1",
    timestamp:   Date.now(),
    windSpeed:   Number(windSpeed.toFixed(2)),
    rotorSpeed:  Number(rotorSpeed.toFixed(1)),
    temperature: Number(temperature.toFixed(1)),
    vibration:   Number(vibration.toFixed(2)),
    power:       Number(power.toFixed(1))
};
msg.t = p;
msg.payload = { ...p };        // 与原结构保持一致

msg.TableName = "TurbineData";
msg.Item = {
    turbineId:   { S: p.turbineId },
    timestamp:   { S: String(p.timestamp) },
    windSpeed:   { N: String(p.windSpeed) },
    rotorSpeed:  { N: String(p.rotorSpeed) },
    temperature: { N: String(p.temperature) },
    vibration:   { N: String(p.vibration) },
    power:       { N: String(p.power) }
};

// --------------- store current values ---------------
context.set('last', { windSpeed, rotorSpeed, temperature, vibration, power });

return msg;

// Function: callGoogleGemini
// Prepare and send a request to Google Gemini 1.5-Flash using the sensor data in msg.payload

// 1. 从环境变量读 API Key
const apiKey = env.get("GOOGLE_API_KEY");

// 2. 构造 HTTP 请求的 URL（model 作为路径参数）
msg.url    = "https://generativelanguage.googleapis.com/v1beta/models/gemini-1.5-flash:generateContent?key=" + apiKey;
// 3. 指定 POST 方法
msg.method = "POST";
// 4. 设置请求头
msg.headers = { "Content-Type": "application/json" };

// 5. 拼 prompt 文本（从上游 msg.payload 取传感器数值）
const p = msg.payload;
const promptText =
`You are a wind turbine fault detection assistant.
Model: 2017 COE Market Average 2.3 MW
Ranges:
- Wind speed: 3–25 m/s (no generation below 3 m/s; shutdown above 25 m/s)
- Rotor speed: 10–25 rpm
- Gearbox oil temperature: 45–65 °C
- Vibration level: ≤2.8 mm/s normal; 2.8–4.5 mm/s warning; >4.5 mm/s alarm
- Output power: 0–2300 kW (ramp up to 2300 kW in 3–11 m/s; maintain at 2300 in 11–25 m/s; shutdown above 25 m/s)

Current readings:
- temperature: ${p.temperature}
- vibration:   ${p.vibration}
- rotorSpeed:  ${p.rotorSpeed}
- power:       ${p.power}

Return strictly JSON in this format:
{"result":"NORMAL|FAULT","reason":"brief explanation"}`;

// 6. 构造符合 GenerateContentRequest 的请求体
msg.payload = {
  // contents 数组，每项是一个 Content 对象，需用 parts[] 包裹 text
  contents: [
    {
      parts: [
        { text: promptText }
      ]
    }
  ],
  // generationConfig 对应官方文档里的 GenerationConfig
  generationConfig: {
    temperature:      0.0,
    maxOutputTokens: 128
  }
};

return msg;

// Function: parseAIResult (Function2)
// 将 HTTP Request 返回的字符串化 JSON 解析成 {result, reason}

let respStr = msg.payload;

// 1. 先把 respStr 转成 JS 对象
let respObj;
try {
    respObj = JSON.parse(respStr);
} catch (e) {
    node.error("Invalid JSON from HTTP response: " + e.message, msg);
    return null;
}

// 2. 提取 AI 输出的带 ```json 代码块的文本
let raw = respObj.candidates?.[0]?.content?.parts?.[0]?.text;
if (typeof raw !== 'string') {
    node.error("No AI content found in respObj", msg);
    return null;
}

// 3. 去掉开头的 ```json 和结尾的 ```
raw = raw
    .replace(/^```json[\r\n]*/, "")
    .replace(/```[\r\n]*$/, "")
    .trim();

// 4. 解析内部的 JSON 字符串
let resultObj;
try {
    resultObj = JSON.parse(raw);
} catch (e) {
    node.error("Invalid inner JSON: " + e.message, msg);
    resultObj = { result: "ERROR", reason: "Invalid JSON" };
}

// 5. 将最终结果写入 msg.payload 并返回
msg.payload = {
    result: resultObj.result,
    reason: resultObj.reason
};
return msg;

// Function: prepareS3LogForPutObject
// 这里改成用 msg.t 来读最初的风机数据

// 1️⃣ 拿到原始模拟数据
const data = msg.t;
if (!data) {
    node.error("msg.t is undefined – 没有原始传感器数据", msg);
    return null;
}

// 2️⃣ 拿到 AI 结果
const ai = msg.payload;
if (!ai || typeof ai.result !== 'string') {
    node.error("msg.payload 不包含 AI 结果", msg);
    return null;
}
msg.ai = ai

// 3️⃣ 组装日志对象
const now = new Date().toISOString();
const logObj = {
    turbineId: data.turbineId,
    timestamp: data.timestamp,
    windSpeed: data.windSpeed,
    rotorSpeed: data.rotorSpeed,
    temperature: data.temperature,
    vibration: data.vibration,
    power: data.power,
    result: ai.result,
    reason: ai.reason
};

// 4️⃣ 填写 S3 PutObject 所需字段
msg.Bucket = "my-turbine-logs";       // 你的 S3 bucket
msg.Key = `logs/${now}.json`;      // 存到 logs/2025-…Z.json
msg.Body = JSON.stringify(logObj);  // Body 必须是字符串
msg.ContentType = "application/json";      // 可选，标明 JSON

return msg;

