// msg.t        — 你的原始风机数据对象
// msg.payload  — parseAIResult 后的 { result, reason }

// 1) 指定要发到哪个 SNS 主题
msg.TopicArn = "arn:aws:sns:ap-southeast-2:135808957475:turbine-alerts";

// 2) 构造你想发的文本
const data = msg.t;
const ai = msg.ai;
msg.Message =
    `🚨 Wind Turbine Fault 🚨
Turbine: ${data.turbineId}
Time   : ${new Date(data.timestamp).toLocaleString()}

Result : ${ai.result}
Reason : ${ai.reason}

WindSpeed  ${data.windSpeed} m/s
RotorSpeed ${data.rotorSpeed} rpm
Temperature ${data.temperature} °C
Vibration  ${data.vibration} mm/s
Power      ${data.power} kW
`;

return msg;
